import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.dMg474VA.js";const h=JSON.parse('{"title":"Feature Inventory & Architectural Traces","description":"","frontmatter":{},"headers":[],"relativePath":"01-features.md","filePath":"01-features.md"}'),o={name:"01-features.md"};function n(s,e,c,l,u,d){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="feature-inventory-architectural-traces" tabindex="-1">Feature Inventory &amp; Architectural Traces <a class="header-anchor" href="#feature-inventory-architectural-traces" aria-label="Permalink to &quot;Feature Inventory &amp; Architectural Traces&quot;">​</a></h1><h2 id="f1-multi-algorithm-rate-limiting-engine" tabindex="-1">F1: Multi-Algorithm Rate Limiting Engine <a class="header-anchor" href="#f1-multi-algorithm-rate-limiting-engine" aria-label="Permalink to &quot;F1: Multi-Algorithm Rate Limiting Engine&quot;">​</a></h2><h3 id="technical-description" tabindex="-1">Technical Description <a class="header-anchor" href="#technical-description" aria-label="Permalink to &quot;Technical Description&quot;">​</a></h3><p>Supports five interchangeable algorithms per route:</p><ol><li><strong>Token Bucket</strong>: Replenishes tokens at a fixed rate up to capacity; permits bursts.</li><li><strong>Leaky Bucket</strong>: Queues and leaks requests at constant speed; smooths traffic.</li><li><strong>Fixed Window</strong>: Counters reset at clock boundaries; simple but vulnerable to 2x boundary bursts.</li><li><strong>Sliding Window Log</strong>: Stores sorted timestamps; perfectly accurate but $O(N)$ memory.</li><li><strong>Sliding Window Counter</strong>: Interpolates between current and previous window counts; $O(1)$ memory with &lt;0.1% boundary error.</li></ol><ul><li><strong>Primary Source</strong>: <code>src/algorithms/</code></li><li><strong>Complexity</strong>: $O(1)$ time and memory for Token Bucket and Sliding Window Counter.</li></ul><h3 id="say-it-out-loud" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;I implemented five distinct rate limiting algorithms to allow fine-tuned protection across different API endpoints. For burst-tolerant endpoints like login submissions, we use Token Bucket, which allows momentary bursts up to capacity while enforcing a strict steady-state refill rate. For expensive database reports, we use Leaky Bucket to smooth traffic into a continuous, uniform stream. For standard REST APIs, we default to Sliding Window Counter: it weights request counts from the previous and current window, eliminating the classic double-burst vulnerability of fixed windows while using constant O(1) memory.&quot;</p></blockquote><hr><h2 id="f2-atomic-redis-lua-script-pipeline-in-memory-fallback" tabindex="-1">F2: Atomic Redis Lua Script Pipeline &amp; In-Memory Fallback <a class="header-anchor" href="#f2-atomic-redis-lua-script-pipeline-in-memory-fallback" aria-label="Permalink to &quot;F2: Atomic Redis Lua Script Pipeline &amp; In-Memory Fallback&quot;">​</a></h2><h3 id="technical-description-1" tabindex="-1">Technical Description <a class="header-anchor" href="#technical-description-1" aria-label="Permalink to &quot;Technical Description&quot;">​</a></h3><p>Executes rate limit state checks, refills, decrements, and TTL updates in a single atomic Lua script executed inside Redis. If Redis fails or times out (50ms limit), the storage layer seamlessly falls back to an in-memory store.</p><ul><li><strong>Primary Source</strong>: <code>packages/store-redis/</code>, <code>packages/store-memory/</code></li><li><strong>Race Condition Immunity</strong>: Guarantees zero over-allocation across hundreds of concurrent gateway replicas.</li></ul><h3 id="say-it-out-loud-1" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud-1" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;To prevent race conditions in a distributed cluster, I executed all rate-limit evaluations via atomic Lua scripts directly on the Redis server. Without Lua, checking a client&#39;s quota and then decrementing it requires multiple round-trips; under high concurrency, fifty requests can all read &#39;count=99&#39; and pass through before any write occurs. Our Lua script evaluates the token balance, calculates replenishment based on elapsed time, deducts the token cost, and sets the TTL atomically in a single network hop. Furthermore, I built a circuit breaker on the Redis client: if Redis becomes unreachable, the gateway degrades to an in-memory fallback within 50 milliseconds, ensuring zero service disruption.&quot;</p></blockquote><hr><h2 id="f3-client-identity-scopes-dynamic-route-costs" tabindex="-1">F3: Client Identity, Scopes &amp; Dynamic Route Costs <a class="header-anchor" href="#f3-client-identity-scopes-dynamic-route-costs" aria-label="Permalink to &quot;F3: Client Identity, Scopes &amp; Dynamic Route Costs&quot;">​</a></h2><h3 id="technical-description-2" tabindex="-1">Technical Description <a class="header-anchor" href="#technical-description-2" aria-label="Permalink to &quot;Technical Description&quot;">​</a></h3><p>Resolves client identity using a prioritized cascade: Bearer JWT claims -&gt; API Key -&gt; IP Subnet (CIDR /24 mask). Evaluates route costs dynamically based on HTTP method, payload size, and query parameters.</p><ul><li><strong>Primary Source</strong>: <code>src/identity/</code>, <code>src/policy/rule.py</code></li></ul>',20)])])}const p=t(o,[["render",n]]);export{h as __pageData,p as default};
